# The inf-sup constant and the softest plastic kernel modes on unstructured
# meshes of the unit cube generated by Cubit (tetmesh, size 1/n, the
# condition-number smoother of the punch meshes; cubit-cube/cube<n>.jou),
# converted to P2 with straight edges.  Referee request M10, and the check of
# the perturbed-mesh result of plastic_jitter.jl on meshes of production
# quality.
#
#   julia --project=. research/tet15-p1/prototype/cubit_cube.jl
ENV["PE_NOMAIN"] = "1"; ENV["KS_NOMAIN"] = "1"
include("plastic_ext.jl")
include("kappa_sweep.jl")
using DelimitedFiles

const DIR = joinpath(@__DIR__, "cubit-cube")

function cubit_mesh(n)
    X = Matrix(readdlm(joinpath(DIR, "cube$(n)_coords.txt"))')
    c = Matrix{Int}(readdlm(joinpath(DIR, "cube$(n)_conn.txt"), Int)')
    for e in axes(c, 2)
        P = X[:, c[:, e]]
        det([P[:, 2] - P[:, 1]  P[:, 3] - P[:, 1]  P[:, 4] - P[:, 1]]) < 0 &&
            ((c[3, e], c[4, e]) = (c[4, e], c[3, e]))
    end
    return promote_to_p2(X, c)
end

function beta_from(a, m)
    F  = cholesky(Symmetric(a.Kh1))
    Gt = Matrix(a.G')
    Z  = Matrix(F.L \ Gt[F.p, :])
    W  = m == 1 ? Z ./ Vector(sqrt.(diag(a.M)))' :
                  Matrix(Z / cholesky(Symmetric(Matrix(a.M))).U)
    sv = sort(svdvals(W))
    r  = rank(Matrix(a.G); rtol = 1e-10)
    idx = length(sv) - r + 1
    return (1 <= idx <= length(sv)) ? sv[idx] : NaN, a.np - r
end

function quality(X, conn, e)
    P = X[:, conn[1:4, e]]
    V = det([P[:, 2] - P[:, 1]  P[:, 3] - P[:, 1]  P[:, 4] - P[:, 1]]) / 6
    l2 = sum(sum(abs2, P[:, a] - P[:, b]) for (a, b) in _TET_EDGES) / 6
    return 6 * sqrt(2) * V / l2^1.5
end

function elem_div2(X, conn, bubble, nu_nodal, v)
    _, gmap = free_dofs(X)
    nelem = size(conn, 2)
    _, fmap = bubble in (:face, :full) ? face_table(X, conn, _BC_ALL) : (0, zeros(Int, 4, nelem))
    el = ref_element(2); qp, qw = tet_rule(6)
    out = zeros(nelem)
    for e in 1:nelem
        Xe = X[:, conn[:, e]]
        rows = element_rows(conn, e, gmap, bubble, nelem, nu_nodal, fmap)
        ue = [r == 0 ? 0.0 : v[r] for r in rows]
        for q in eachindex(qw)
            xi = qp[:, q]
            Jm = Xe * RFE.shape_function_gradient(el, xi)
            _, dNr = shapes(bubble, xi); dN = dNr / Jm
            d = sum(ue[NSD * (A - 1) + k] * dN[A, k] for A in axes(dN, 1), k in 1:NSD)
            out[e] += qw[q] * det(Jm) * d^2
        end
    end
    return out
end

const CPAIRS = (("P2/P1c (TH)", _P1C, :none), ("P2/P0", 1, :none),
                ("P2+face/P0", 1, :face), ("P2+int+face/P1disc", 4, :full))

function main()
    println("Cubit meshes of the unit cube, whole boundary fixed.")
    "plastic" in ARGS || betas()
    plastic()
end

function betas()
    println("\nbeta_h (null = n_p - rank G)")
    for (label, m, bubble) in CPAIRS
        row = String[]
        for n in 2:6
            X, conn = cubit_mesh(n)
            nvert = m == _P1C ? size(readdlm(joinpath(DIR, "cube$(n)_coords.txt")), 1) : 0
            a = assemble_all(X, conn, 2, m; bubble, nvert)
            b, nn = beta_from(a, m)
            push!(row, "n=$n: $(round(b, sigdigits = 4)) ($nn)")
        end
        println(rpad(label, 20), join(row, "  ")); flush(stdout)
    end
end

function plastic()
    for (fname, flow) in (("axial", N_AXIAL), ("shear", N_SHEAR))
        println("\nbeta = 1, flow $fname; twenty lowest modes on ker G: lam_1, lam_20, ",
                "n_dil = #(r_v > 0.1), r_v of the five lowest; lowest dilatational mode: lam, r_v, ",
                "share of int (div v)^2 in its 3 largest elements, min quality of those")
        for (label, m, bubble) in reverse(CPAIRS), n in (3, 4, 5, 6, 7, 8, 10)
            m == _P1C && n > 6 && continue
            X, conn = cubit_mesh(n)
            nvert = m == _P1C ? size(readdlm(joinpath(DIR, "cube$(n)_coords.txt")), 1) : 0
            ap = assemble_all(X, conn, 2, m; bubble, nvert, flow, beta = 1.0)
            lp, vp, nit = kernel_modes(ap, ap.Kdev ./ 2; k = 20, b = 40)
            rv = [dilatation(ap, vp[:, i]) for i in 1:length(lp)]
            dil = findall(>(0.1), rv)
            s = "-"
            if !isempty(dil) && m != _P1C
                i = dil[1]
                ed = elem_div2(X, conn, bubble, ap.nu_nodal, vp[:, i])
                p = sortperm(ed, rev = true)[1:3]
                s = "lam $(round(lp[i], sigdigits = 3)) r_v $(round(rv[i], sigdigits = 3)) top3 " *
                    "$(round(sum(ed[p]) / sum(ed), sigdigits = 2)) q $(round(minimum(quality(X, conn, e) for e in p), sigdigits = 3))"
            elseif !isempty(dil)
                s = "lam $(round(lp[dil[1]], sigdigits = 3)) r_v $(round(rv[dil[1]], sigdigits = 3))"
            end
            println(rpad(label, 20), rpad("n=$n", 6), rpad(string(ap.nu), 7),
                    rpad(string(round(lp[1], sigdigits = 3)), 8), rpad(string(round(lp[end], sigdigits = 3)), 8),
                    rpad(string(length(dil)), 4), join(fmt.(rv[1:5])), "| ", s, "  (", nit, " it)")
            flush(stdout)
        end
    end
end

get(ENV, "CC_NOMAIN", "") == "1" || main()
